// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Logout Revoke the caller's refresh token (and its rotation family)
	// (POST /v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RequestOtp Send a one-time sign-in code to an e-mail address
	// (POST /v1/auth/otp)
	RequestOtp(ctx context.Context, request RequestOtpRequestObject) (RequestOtpResponseObject, error)
	// CreateToken Exchange an e-mail one-time code (or a refresh token) for tokens
	// (POST /v1/auth/token)
	CreateToken(ctx context.Context, request CreateTokenRequestObject) (CreateTokenResponseObject, error)
	// ListMakes List vehicle makes
	// (GET /v1/catalogue/makes)
	ListMakes(ctx context.Context, request ListMakesRequestObject) (ListMakesResponseObject, error)
	// ListModels List models of a make
	// (GET /v1/catalogue/makes/{makeId}/models)
	ListModels(ctx context.Context, request ListModelsRequestObject) (ListModelsResponseObject, error)
	// ListVariants Query concrete variants (fuel, displacement, year)
	// (GET /v1/catalogue/variants)
	ListVariants(ctx context.Context, request ListVariantsRequestObject) (ListVariantsResponseObject, error)
	// GetVariant Get one variant
	// (GET /v1/catalogue/variants/{variantId})
	GetVariant(ctx context.Context, request GetVariantRequestObject) (GetVariantResponseObject, error)
	// GetHealth Liveness / readiness probe
	// (GET /v1/health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// DeleteMe Delete the caller's account and all associated data
	// (DELETE /v1/me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// GetMe Get the caller's profile
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Update the caller's profile
	// (PATCH /v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// GetPointsBalance Points balance (Remote-only feature)
	// (GET /v1/me/points)
	GetPointsBalance(ctx context.Context, request GetPointsBalanceRequestObject) (GetPointsBalanceResponseObject, error)
	// ListPointsLedger Points history (Remote-only feature)
	// (GET /v1/me/points/ledger)
	ListPointsLedger(ctx context.Context, request ListPointsLedgerRequestObject) (ListPointsLedgerResponseObject, error)
	// ListRanking Leaderboard for a metric and period (Remote-only feature)
	// (GET /v1/rankings/{metric})
	ListRanking(ctx context.Context, request ListRankingRequestObject) (ListRankingResponseObject, error)
	// GetMyRanking The caller's position for a metric and period (Remote-only feature)
	// (GET /v1/rankings/{metric}/me)
	GetMyRanking(ctx context.Context, request GetMyRankingRequestObject) (GetMyRankingResponseObject, error)
	// ListCountries List supported countries
	// (GET /v1/reference/countries)
	ListCountries(ctx context.Context, request ListCountriesRequestObject) (ListCountriesResponseObject, error)
	// ListRegions List regions of a country
	// (GET /v1/reference/countries/{countryCode}/regions)
	ListRegions(ctx context.Context, request ListRegionsRequestObject) (ListRegionsResponseObject, error)
	// GetStatsSummary Aggregate driving statistics for a period (Remote-only feature)
	// (GET /v1/stats/summary)
	GetStatsSummary(ctx context.Context, request GetStatsSummaryRequestObject) (GetStatsSummaryResponseObject, error)
	// UploadTelemetryBatch Upload a batch of telemetry samples and events for one trip
	// (POST /v1/telemetry/batches)
	UploadTelemetryBatch(ctx context.Context, request UploadTelemetryBatchRequestObject) (UploadTelemetryBatchResponseObject, error)
	// ListTrips List trips (newest first, or in change order for incremental sync)
	// (GET /v1/trips)
	ListTrips(ctx context.Context, request ListTripsRequestObject) (ListTripsResponseObject, error)
	// UploadTrips Upsert a batch of trip summaries (idempotent)
	// (POST /v1/trips/batch)
	UploadTrips(ctx context.Context, request UploadTripsRequestObject) (UploadTripsResponseObject, error)
	// ListDrivingDays Calendar days on which the caller drove
	// (GET /v1/trips/days)
	ListDrivingDays(ctx context.Context, request ListDrivingDaysRequestObject) (ListDrivingDaysResponseObject, error)
	// ListTripDeletions Trips deleted since a sync token (incremental sync)
	// (GET /v1/trips/deletions)
	ListTripDeletions(ctx context.Context, request ListTripDeletionsRequestObject) (ListTripDeletionsResponseObject, error)
	// DeleteTrip Delete a trip with its telemetry
	// (DELETE /v1/trips/{tripId})
	DeleteTrip(ctx context.Context, request DeleteTripRequestObject) (DeleteTripResponseObject, error)
	// GetTrip Get one trip summary
	// (GET /v1/trips/{tripId})
	GetTrip(ctx context.Context, request GetTripRequestObject) (GetTripResponseObject, error)
	// ListTripEvents Read back a trip's driving events
	// (GET /v1/trips/{tripId}/events)
	ListTripEvents(ctx context.Context, request ListTripEventsRequestObject) (ListTripEventsResponseObject, error)
	// ListTripSamples Read back a trip's telemetry samples (chronological)
	// (GET /v1/trips/{tripId}/samples)
	ListTripSamples(ctx context.Context, request ListTripSamplesRequestObject) (ListTripSamplesResponseObject, error)
	// ListVehicles List the caller's vehicles
	// (GET /v1/vehicles)
	ListVehicles(ctx context.Context, request ListVehiclesRequestObject) (ListVehiclesResponseObject, error)
	// CreateVehicle Register a vehicle
	// (POST /v1/vehicles)
	CreateVehicle(ctx context.Context, request CreateVehicleRequestObject) (CreateVehicleResponseObject, error)
	// DeleteVehicle Delete a vehicle
	// (DELETE /v1/vehicles/{vehicleId})
	DeleteVehicle(ctx context.Context, request DeleteVehicleRequestObject) (DeleteVehicleResponseObject, error)
	// GetVehicle Get one vehicle
	// (GET /v1/vehicles/{vehicleId})
	GetVehicle(ctx context.Context, request GetVehicleRequestObject) (GetVehicleResponseObject, error)
	// UpdateVehicle Update a vehicle (JSON merge patch, optimistic concurrency)
	// (PATCH /v1/vehicles/{vehicleId})
	UpdateVehicle(ctx context.Context, request UpdateVehicleRequestObject) (UpdateVehicleResponseObject, error)
	// ListDtcReports List DTC reports for a vehicle (newest first)
	// (GET /v1/vehicles/{vehicleId}/dtc-reports)
	ListDtcReports(ctx context.Context, request ListDtcReportsRequestObject) (ListDtcReportsResponseObject, error)
	// CreateDtcReport Record a diagnostic trouble code (DTC) read or clear
	// (POST /v1/vehicles/{vehicleId}/dtc-reports)
	CreateDtcReport(ctx context.Context, request CreateDtcReportRequestObject) (CreateDtcReportResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
